pub fn decode_cyclic(s: &Vec<i8>) -> Vec<i8> {
    let l = s.len();
    let p = l - (l % 3); // largest multiple of 3 <= l

    // Start with a copy so the suffix [p, l) is already unchanged.
    let mut res = s.clone();

    // For each full triplet [k, k+1, k+2], write:
    // res[k]   = s[k+2]
    // res[k+1] = s[k]
    // res[k+2] stays as s[k+2] (since only i mod 3 = 0 or 1 are specified)
    for k in (0..p).step_by(3) {
        res[k] = s[k + 2];
        res[k + 1] = s[k];
    }

    res
}